/* Object lists, detail evidence and local action drafts, using isolated fixtures. */
const summaryPanelContent=panelContent;
const objectViews=new Map();
function capKey(key){return /^(sem|seo|geo):\d+$/.test(key)&&!!businessRecords[key.split(':')[0]][Number(key.split(':')[1])];}
function configFor(key){const [module,index]=key.split(':');return businessRecords[module][Number(index)];}
function objectId(key,row){return `${key.split(':')[0].toUpperCase()}-${String(Number(key.split(':')[1])+1).padStart(2,'0')}-${String(row+1).padStart(2,'0')}`;}
function listMarkup(key,scope){const c=configFor(key);return `<h2>${esc(capabilities[key.split(':')[0]][key.split(':')[1]])}</h2><p class="fixture-note">流程演示 · 以下独立业务场景不计入首页指标。当前配置与流程状态，不提供历史快照。</p><p>${esc(c[5])}</p><div class="object-toolbar"><label>搜索对象 <input type="search" data-object-search placeholder="名称、范围或状态"></label><label>状态 <select data-object-status><option value="all">全部</option>${[...new Set(c[4].map(r=>r[3]))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></label></div><div class="object-rows" data-list-key="${key}">${objectTable(key,'','all')}</div><p class="scope-label">首页选择：${scopes[scope]}。列表为演示配置快照；对象中的报告、采集和发布按各自标注周期查看。</p>`;}
function objectTable(key,query,status){const c=configFor(key);const rows=c[4].map((r,i)=>({r,i})).filter(({r})=>r.join(' ').toLowerCase().includes(query.toLowerCase())&&(status==='all'||r[3]===status));return rows.length?table(c.slice(0,4).concat('操作'),rows.map(({r,i})=>r.map(v=>esc(v)).concat(`<button class="table-action" data-object="${i}">查看详情 →</button>`))):'<div class="object-empty">没有符合条件的记录。<button class="text-button" data-object-reset>清除筛选</button></div>';}
panelContent=function(key,scope){return capKey(key)?listMarkup(key,scope):summaryPanelContent(key,scope);};
function panelFor(el){return panels.get(el.closest('.detail-window')?.id);}
function viewFor(p){if(!objectViews.has(p.id))objectViews.set(p.id,{row:null,query:'',status:'all',tab:'facts'});return objectViews.get(p.id);}
function showObject(p,row,tab='facts'){const c=configFor(p.key),v=viewFor(p);v.row=row;v.tab=tab;const r=c[4][row],id=objectId(p.key,row);if(!r)return;const fields=table(['字段','记录'],c.slice(0,4).map((n,i)=>[esc(n),esc(r[i])]).concat([['记录编号',id],['所属客户','诺德新材料 · 流程演示'],['数据性质','独立演示记录，未连接模块'],['状态观测','2026.09.06 · 演示当前状态']]));const evidence=`<h3>证据记录</h3>${table(['检查点','当前演示记录','是否满足验收'],[['记录来源',`流程样例 ${id}`,'演示快照'],[esc(c[1]),esc(r[1]),'已记录，待业务核对'],[esc(c[2]),esc(r[2]),'已记录，待业务核对'],['流程状态',esc(r[3]),'不等于效果验收'],['验收条件',esc(c[6]),'正式验证尚未执行']])}<p>当前展示的是演示记录。验收时还需核对实际发布、操作回执或复查结果；记录状态本身不作为完成证明。</p>${p.key==='seo:5'?'<button class="secondary-button" data-action="evidence" data-key="images">查看已有 20 张图片复查示例</button>':p.key==='seo:4'&&row===0?'<button class="secondary-button" data-action="evidence" data-key="titles">查看已有 6 页标题复查示例</button>':p.key==='geo:2'?'<button class="secondary-button" data-panel="visibility">查看已有 12 条来源样本</button>':''}`;const actions=`<h3>建议处理顺序</h3><ol class="steps"><li>核对当前记录：${esc(r[0])}，确认范围为 ${esc(r[1])}。</li><li>${esc(c[5])}</li><li>约定验收：${esc(c[6])}。</li><li>指定负责人和复核日期，保存为行动草稿。</li></ol><button class="primary-button" data-object-draft>拟定关联行动</button><p>保存只进入本地待办与进度，不会修改广告、发布内容或执行采集。</p>`;
p.el.querySelector('.window-body').innerHTML=`<button class="text-button" data-object-back>← ${esc(capabilities[p.key.split(':')[0]][p.key.split(':')[1]])} / 返回列表</button><div class="object-heading"><div><span class="scope-label">${id} · 独立流程演示</span><h2>${esc(r[0])}</h2></div><span class="object-status">${esc(r[3])}</span></div><div class="object-tabs" role="tablist" aria-label="对象详情">${[['facts','基本信息'],['evidence','证据与验收'],['actions','处理与行动']].map(([k,n])=>`<button role="tab" aria-selected="${tab===k}" data-object-tab="${k}" class="${tab===k?'selected':''}">${n}</button>`).join('')}</div><div role="tabpanel">${tab==='facts'?fields:tab==='evidence'?evidence:actions}</div>`;p.el.querySelector('.window-body').scrollTop=0;$('#contextTitle').textContent=`${r[0]} · ${id} · 演示当前状态`;p.el.querySelector('[data-object-back]').focus();}
function returnList(p){const v=viewFor(p);p.el.querySelector('.window-body').innerHTML=listMarkup(p.key,p.scope);const search=p.el.querySelector('[data-object-search]'),select=p.el.querySelector('[data-object-status]');search.value=v.query;select.value=v.status;p.el.querySelector('.object-rows').innerHTML=objectTable(p.key,v.query,v.status);v.row=null;focusPanel(p);search.focus();}
let objectDraftContext=null;
function draftObject(p,existing){const v=viewFor(p),c=configFor(p.key),r=c[4][v.row];objectDraftContext={key:p.key,row:v.row,scope:p.scope,id:existing?.id};state.dialog={type:'objectDraft'};showDialog('关联行动 · 待确认方案',`<h2>${existing?'编辑':'拟定'}关联行动</h2><p class="dialog-lead">${esc(r[0])} · ${objectId(p.key,v.row)} · 当前配置演示</p><form id="objectDraftForm"><label>行动标题<input name="title" required maxlength="120" value="${esc(existing?.title||'核验：'+r[0])}"></label><div class="object-form-row"><label>负责人<input name="owner" required maxlength="60" value="${esc(existing?.owner||p.key.split(':')[0].toUpperCase()+' 运营负责人')}"></label><label>复核日期<input name="due" type="date" required value="${esc(existing?.due||'2026-09-10')}"></label></div><label>处理说明<textarea name="note" required maxlength="1500" rows="3">${esc(existing?.note||c[5])}</textarea></label><label>验收条件<textarea name="criterion" required maxlength="1000" rows="3">${esc(existing?.criterion||c[6])}</textarea></label><div class="dialog-footer"><span class="muted">仅保存待确认方案，尚未交给负责人</span><button type="submit" class="primary-button">保存关联行动</button></div></form>`);}
document.addEventListener('submit',e=>{if(e.target.id!=='objectDraftForm')return;e.preventDefault();const form=e.target;if(!form.reportValidity()||!objectDraftContext)return;const c=objectDraftContext,d=new FormData(form);if(['title','owner','note','criterion'].some(k=>!d.get(k).trim())){toast('请填写完整的行动信息。');return;}const duplicate=localDrafts.find(t=>t.sourceObject?.key===c.key&&t.sourceObject.row===c.row&&t.status==='draft'&&t.id!==c.id);if(duplicate){toast('这个对象已有行动草稿，请到待办与进度编辑。');return;}const issue=c.key.startsWith('sem')?'allocation':c.key.startsWith('seo')?'images':'visibility';const task={id:c.id||'LOCAL-'+Date.now().toString(36).toUpperCase(),title:d.get('title').trim(),owner:d.get('owner').trim(),due:d.get('due'),note:d.get('note').trim(),criterion:d.get('criterion').trim(),status:'draft',issue,plan:'verify',reduction:0,sourceObject:{key:c.key,row:c.row,scope:c.scope}};if(c.id)localDrafts=localDrafts.map(t=>t.id===c.id?task:t);else localDrafts.unshift(task);const ok=persist();closeDialog();renderTasks();if(ok)toast('关联行动已保存，可在待办与进度查看。');addMessage('assistant',`已保存 <strong>${esc(task.title)}</strong>，关联 ${objectId(c.key,c.row)}。尚未交给负责人。`,[{label:'查看行动',task:task.id}]);});
const originalShowTask=showTask;
showTask=function(id){originalShowTask(id);const t=allTasks().find(t=>t.id===id);if(!t?.sourceObject)return;const s=t.sourceObject;const fact=$('#dialogBody .detail-facts .fact:last-child p');if(fact)fact.textContent=configFor(s.key)[4][s.row][0]+' · '+objectId(s.key,s.row);const link=$('#dialogBody [data-action="taskContext"]');if(link){link.removeAttribute('data-action');link.dataset.returnObject=id;link.textContent='回到关联对象 →';}};
const originalShowDraft=showDraft;
showDraft=function(id){const t=allTasks().find(t=>t.id===id);if(!t?.sourceObject){originalShowDraft(id);return;}const s=t.sourceObject;openPanel(s.key,s.scope);const p=[...panels.values()].find(p=>p.key===s.key&&p.scope===s.scope);viewFor(p).row=s.row;p.el.hidden=true;dock();draftObject(p,t);};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const p=panelFor(b);if(p&&capKey(p.key)){if(b.hasAttribute('data-object'))showObject(p,Number(b.dataset.object));if(b.dataset.objectTab)showObject(p,viewFor(p).row,b.dataset.objectTab);if(b.hasAttribute('data-object-back'))returnList(p);if(b.hasAttribute('data-object-reset')){Object.assign(viewFor(p),{query:'',status:'all'});returnList(p);}if(b.hasAttribute('data-object-draft'))draftObject(p);}if(b.dataset.returnObject){const t=allTasks().find(t=>t.id===b.dataset.returnObject);if(!t)return;closeDialog();const s=t.sourceObject;openPanel(s.key,s.scope);showObject([...panels.values()].find(p=>p.key===s.key&&p.scope===s.scope),s.row);}});
function filterObjects(e){if(!e.target.matches('[data-object-search],[data-object-status]'))return;const p=panelFor(e.target),v=viewFor(p);v.query=p.el.querySelector('[data-object-search]').value.trim();v.status=p.el.querySelector('[data-object-status]').value;p.el.querySelector('.object-rows').innerHTML=objectTable(p.key,v.query,v.status);}
document.addEventListener('input',filterObjects);document.addEventListener('change',filterObjects);
/* Preserve object context for the existing assistant rather than falling back to a module. */
const generalReply=reply;
reply=function(q){const p=focusedPanel,v=p&&objectViews.get(p.id);if(!p||v?.row==null||!capKey(p.key)){generalReply(q);return;}const c=configFor(p.key),r=c[4][v.row];addMessage('user',q);addMessage('assistant',`<p>当前对象：<strong>${esc(r[0])}</strong>（${objectId(p.key,v.row)}），状态为 ${esc(r[3])}。</p><p>记录范围：${esc(r[1])}；${esc(c[2])}：${esc(r[2])}。</p><p>下一步：${esc(c[5])}</p><p>验收条件：${esc(c[6])}。</p><p>以上是此演示对象的固定指引，尚未进行模型分析。</p>`);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-win="explain"]');if(!b)return;const p=panelFor(b),v=p&&objectViews.get(p.id);if(v?.row==null)return;e.stopImmediatePropagation();focusedPanel=p;p.el.hidden=innerWidth<=620;showChat();reply('请解释这个对象的状态和下一步');dock();},true);
/* Business-first landing, with analysis opened on demand. */
const boardRender=renderDashboard;
renderDashboard=function(){boardRender();$('#page-dashboard .eyebrow').textContent='诺德新材料 / 经营工作台';$('#page-dashboard h1').textContent='经营总览';$('#page-dashboard .dashboard-header p:last-child').textContent='查看业务表现、跟进执行，核对每一项结果。';$('#page-dashboard .cap-explorer h2').textContent='业务明细';$('#page-dashboard .cap-explorer .scope-label').textContent='按业务进入对象列表，查看详情、证据与关联行动。独立流程示例不计入首页指标。';};
const moduleRender=renderModule;
renderModule=function(){moduleRender();$('#page-module').insertAdjacentHTML('beforeend',`<section class="cap-explorer"><h2>继续查看业务明细</h2><div class="cap-column">${capabilities[state.module].map((name,index)=>openButton(state.module+':'+index,name)).join('')}</div></section>`);};
const pagePositions=new Map(),previousNavigate=navigate;
navigate=function(page){pagePositions.set(state.page,$('#pageScroll').scrollTop);previousNavigate(page);$('#pageScroll').scrollTop=pagePositions.get(page)||0;};
document.addEventListener('click',e=>{if(e.target.closest('a.brand')){e.preventDefault();e.stopImmediatePropagation();navigate('dashboard');}},true);
const objectDetailRender=showObject;
showObject=function(p,row,tab='facts'){objectDetailRender(p,row,tab);const c=configFor(p.key),r=c[4][row],m=p.key.split(':')[0],i=Number(p.key.split(':')[1]);const related={sem:[[1,9],[3,11],[3,10],[4,5],[5,11],[6,11],[5,7],[5,2],[11,10],[0,10],[3,2],[5,12],[1,11]],seo:[[4,1],[2,6],[1,3],[2,6],[5,12],[4,12],[7,8],[6,8],[6,9],[8,12],[1,6],[4,12],[5,9]],geo:[[1,4],[2,12],[3,10],[2,12],[3,5],[8,12],[9,8],[8,6],[6,12],[6,12],[2,3],[2,12],[2,8]]}[m][i];const body=p.el.querySelector('.window-body');if(tab==='evidence')body.insertAdjacentHTML('beforeend',`<details class="raw-object"><summary>查看演示原始记录</summary><pre>${esc(JSON.stringify({record_id:objectId(p.key,row),demo:true,included_in_dashboard_totals:false,scope:'current_demo_configuration',fields:Object.fromEntries(c.slice(0,4).map((f,n)=>[f,r[n]]))},null,2))}</pre></details>`);body.insertAdjacentHTML('beforeend',`<div class="related-objects"><h3>相关业务</h3><div class="dash-links">${related.map(k=>openButton(m+':'+k,capabilities[m][k])).join('')}</div><p class="scope-label">进入相关业务列表，保留当前详情以便对照。</p></div>`);};
const baseResetChat=resetChat;
resetChat=function(){if(state.page!=='dashboard'){baseResetChat();return;}$('#chatStream').replaceChildren();addMessage('assistant','<p>从大盘或业务明细选择一个对象，可以查看记录、核对证据，并拟定关联行动。</p><p>打开详情后，分析会跟随你选择的对象。当前为固定规则演示。</p>');updateSuggestions();};
document.addEventListener('keydown',e=>{const t=e.target.closest('[data-object-tab]');if(!t||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=['facts','evidence','actions'],index=keys.indexOf(t.dataset.objectTab),next=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3,p=panelFor(t);showObject(p,viewFor(p).row,keys[next]);p.el.querySelector(`[data-object-tab="${keys[next]}"]`).focus();});
renderDashboard();setMode('fullscreen');resetChat();
